// student_manager.c

#include <stdio.h>

int calculateAverage(int marks[], int size) {
    int sum = 0;

    for (int i = 0; i < size; i++) {
        sum += marks[i];
    }

    return sum / size;
}

void printStudent(char name[], int age) {
    printf("Name: %s\n", name);
    printf("Age: %d\n", age);
}

int main() {
    int marks[5] = {80, 75, 90, 85, 88};
    char name[20] = "Vaibhav";

    int avg = calculateAverage(marks, 5);

    printf("Average Marks: %d\n", avg);

    printStudent(name, 21);

    if (avg > 80)
        printf("Excellent Performance\n");
    else
        printf("Needs Improvement\n");

    for (int i = 0; i < 5; i++) {
        printf("Mark %d = %d\n", i, marks[i]);
    }

    return 0;
}
